#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include "md4c-html.h"
static int cb(const MD_CHAR* data, MD_SIZE size, void* userdata){ return 0; }
static unsigned xs=1; static unsigned rnd(){ xs^=xs<<13; xs^=xs>>17; xs^=xs<<5; return xs; }
static const char alphabet[] = "[]()<>\\\"' abcxyz:/|\n\r\t>!-_*`#";
int main(){
  char buf[4096]; unsigned flags = 0x8ffff; const char* seeds[] = {
    "[a](b \\\"c\\n d)", "[a](b \\\"c\\n d\\n e)", "> [a](b \\\"c\\n> d)", "> [a](b \\\"c\\n>",
    "[x]: y \\\"c\\n d", "> [x]: y \\\"c\\n> d", "[a](b \\n\\\"c", "| [a](b \\\"c\\n| d) |\\n|---|",
    "a|b\\n-| -\\n[a](b \\\"c\\n d)|x", "[a](<b> \\\"c\\n d)", "[a](b \\n \\\"c\\n d\\n )"
  }; int ns=sizeof(seeds)/sizeof(seeds[0]);
  for(unsigned iter=0;;iter++){
    if(iter%10000==0) fprintf(stderr,"iter %u\n",iter);
    int n=0; const char* s=seeds[rnd()%ns]; int sl=strlen(s); memcpy(buf,s,sl); n=sl;
    int muts=1+(rnd()%30);
    for(int m=0;m<muts && n<(int)sizeof(buf)-20;m++){
      int op=rnd()%5;
      if(op==0 && n>0){ int p=rnd()%n; memmove(buf+p,buf+p+1,n-p-1); n--; }
      else if(op==1 && n>0){ buf[rnd()%n]=alphabet[rnd()%(sizeof(alphabet)-1)]; }
      else if(op==2){ int p=rnd()%(n+1), l=1+rnd()%16; memmove(buf+p+l,buf+p,n-p); for(int i=0;i<l;i++) buf[p+i]=alphabet[rnd()%(sizeof(alphabet)-1)]; n+=l; }
      else if(op==3 && n>0){ int p=rnd()%n; int l=1+rnd()%((n-p)>32?32:(n-p)); memmove(buf+p+l,buf+p,n-p); memcpy(buf+p,buf+p+l,l); n+=l; }
      else { int l=1+rnd()%8; for(int i=0;i<l;i++) buf[n++]=alphabet[rnd()%(sizeof(alphabet)-1)]; }
    }
    FILE* f=fopen("/tmp/current.md","wb"); fwrite(buf,1,n,f); fclose(f);
    md_html(buf,n,cb,NULL,flags,0);
  }
}
